def build_manual_examples() -> list[dict]:
    examples = []
    for idx, template in enumerate(TEMPLATES):
        tokens = template["text"].split()[:512]
        labels = ["O"] * len(tokens)
        for span_text, label_type in template["entities"]:
            tag_exact_words(tokens, labels, span_text, label_type)

        tagged = sum(1 for label in labels if label != "O")
        if tagged >= 5:
            examples.append({
                "tokens": tokens,
                "ner_tags": [LABEL2ID[label] for label in labels],
                "metadata": {
                    "source": "manual_templates",
                    "source_id": f"manual:{idx}",
                    "group_id": f"manual:{idx}",
                },
            })
    return examples


if __name__ == "__main__":
    examples = build_manual_examples()
    print(f"Generated {len(examples)} unique manual examples from {len(TEMPLATES)} templates")
